def allocate_cents(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError("total must be an integer excluding bool")
    if not isinstance(weights, list):
        raise TypeError("weights must be a list")
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError("weights must contain integers excluding bool")
    if total < 0:
        raise ValueError("total must be nonnegative")
    if not weights:
        raise ValueError("weights must be nonempty")
    if any(weight <= 0 for weight in weights):
        raise ValueError("weights must be positive")
    denominator = sum(weights)
    allocations = []
    remainders = []
    for weight in weights:
        quotient, remainder = divmod(total * weight, denominator)
        allocations.append(quotient)
        remainders.append(remainder)
    remaining = total - sum(allocations)
    priority = sorted(range(len(weights)), key=lambda index: (-remainders[index], index))
    for index in priority[:remaining]:
        allocations[index] += 1
    return allocations

import math


def categorical_loss_grad(logits, labels):
    if not isinstance(logits, list) or not logits:
        raise ValueError("logits must be a nonempty list of rows")
    if not isinstance(labels, list) or len(labels) != len(logits):
        raise ValueError("labels must match the batch")
    if not isinstance(logits[0], list) or len(logits[0]) < 2:
        raise ValueError("at least two classes are required")
    classes = len(logits[0])
    rows = []
    for row, label in zip(logits, labels):
        if not isinstance(row, list) or len(row) != classes:
            raise ValueError("logits must be rectangular")
        if isinstance(label, bool) or not isinstance(label, int):
            raise ValueError("labels must be integer class indices")
        if not 0 <= label < classes:
            raise ValueError("class index out of range")
        converted = []
        for value in row:
            if not isinstance(value, (int, float)):
                raise ValueError("logits must be finite numbers")
            try:
                value = float(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError("logits must be finite numbers") from exc
            if not math.isfinite(value):
                raise ValueError("logits must be finite numbers")
            converted.append(value)
        rows.append(converted)

    batch = len(rows)
    losses = []
    gradient = []
    for row, label in zip(rows, labels):
        maximum = max(row)
        shifted = [value - maximum for value in row]
        weights = [math.exp(value) for value in shifted]
        denominator = math.fsum(weights)
        gap = maximum - row[label]
        if math.isfinite(gap):
            scaled_gap = gap / batch
        else:
            scaled_gap = maximum / batch - row[label] / batch
        losses.append(scaled_gap + math.log(denominator) / batch)
        gradient.append([
            (weight / denominator - (1.0 if column == label else 0.0)) / batch
            for column, weight in enumerate(weights)
        ])
    try:
        loss = math.fsum(losses)
    except OverflowError:
        loss = math.inf
    return loss, gradient

def check_contract(fn):
    class PortInteger(int):
        pass

    for value in (1, 2, 22, 80, 443, 1024, 32768, 65534, 65535,
                  PortInteger(8080)):
        actual = fn(value)
        assert isinstance(actual, int) and not isinstance(actual, bool), (
            "valid port must return an integer", value, actual
        )
        assert actual == value, ("port changed", value, actual)

    def raises(expected, value):
        try:
            fn(value)
        except expected:
            return
        raise AssertionError(("expected exception", expected.__name__, value))

    for value in (0, -1, -65535, -(10 ** 100), 65536, 65537, 10 ** 100):
        raises(ValueError, value)

    for value in (
        True, False, None, "", "1", "443", "65535", " 80 ",
        1.0, 443.0, 65535.0, -1.5, 0.0, float("nan"),
        float("inf"), b"80", 80 + 0j, [], [80], (), {}, {80}, object()
    ):
        raises(TypeError, value)
